const fail = (status, m, codigo) => [{ json: { ok: false, status, body: { sucesso: false, erro: m, message: m, ...(codigo ? { codigo } : {}) } } }];
const falta = ["CHATWOOT_DOMAIN", "CHATWOOT_API_TOKEN", "CHATWOOT_ACCOUNT_ID"].filter(k => !$env[k]);
if (falta.length) return fail(500, 'PENDENTE_CONFIGURACAO_CHATWOOT: variáveis ausentes no ambiente do Harmonia: ' + falta.join(', '), 'PENDENTE_CONFIGURACAO_CHATWOOT');
if (!/^\d+$/.test(String($env.CHATWOOT_ACCOUNT_ID))) return fail(500, 'PENDENTE_CONFIGURACAO_CHATWOOT: CHATWOOT_ACCOUNT_ID não é numérico', 'PENDENTE_CONFIGURACAO_CHATWOOT');
return [{ json: { ok: true } }];

const fail = (status, m, codigo) => [{ json: { status, body: { sucesso: false, erro: m, message: m, ...(codigo ? { codigo } : {}) } } }];

const lista = ($input.first().json.payload) || [];
const wa = lista.filter(i => i.channel_type === 'Channel::Whatsapp' || i.medium === 'whatsapp');
const pref = String($env.CHATWOOT_WHATSAPP_INBOX_ID || '');
let ib = wa.find(i => String(i.id) === pref) || null;
if (!ib && wa.length === 1) ib = wa[0];
if (!ib && wa.length === 0) return fail(404, 'PENDENTE_CONFIGURACAO: nenhum canal de WhatsApp conectado no Harpa', 'PENDENTE_CONFIGURACAO_WHATSAPP');
if (!ib) return fail(409, 'Mais de um canal de WhatsApp no Harpa; defina CHATWOOT_WHATSAPP_INBOX_ID com o id correto', 'PENDENTE_CONFIGURACAO_WHATSAPP');
const numero = String(ib.phone_number || '').replace(/\D/g, '');
if (!numero) return fail(404, 'O canal de WhatsApp do Harpa não informa número', 'PENDENTE_CONFIGURACAO_WHATSAPP');
return [{ json: { status: 200, body: { numero } } }];

const it = $input.first().json || {};
const e = it.error || it;
const raw = String(e.description || e.message || 'erro desconhecido');
const upstream = Number(e.httpCode || e.statusCode || e.status || (e.cause && e.cause.status) || 0);
const clean = raw.replace(/https?:\/\/\S+/g, '[url]').replace(/(token|api_access_token|authorization)\S*/gi, '[omitido]').slice(0, 300);
const status = upstream === 404 ? 404 : 502;
const m = "Falha ao consultar canais no Harpa" + (upstream ? ' (HTTP ' + upstream + ')' : '') + (true ? ': ' + clean : '');
return [{ json: { status, body: { sucesso: false, erro: m, message: m, origem: "harpa" } } }];
